package com.chx.claims.claim.api;
import com.chx.claims.claim.api.dto.SubmitClaimRequest; import com.chx.claims.claim.application.*; import com.chx.claims.claim.domain.Claim; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/claims") public class ClaimantClaimController { private final ClaimCommandService commands; private final ClaimQueryService queries; public ClaimantClaimController(ClaimCommandService c,ClaimQueryService q){commands=c;queries=q;} @PostMapping public ResponseEntity<Claim> submit(@Valid @RequestBody SubmitClaimRequest r,@RequestHeader("X-User-Id") UUID user){return ResponseEntity.status(HttpStatus.CREATED).body(commands.submit(user,r.policyId(),r.claimType(),r.market(),r.incidentDate(),r.description(),r.claimedAmount(),r.currency()));} @GetMapping public List<Claim> mine(@RequestHeader("X-User-Id") UUID user){return queries.mine(user);} @GetMapping("/{id}") public Claim get(@PathVariable UUID id,@RequestHeader("X-User-Id") UUID user){return queries.get(id,user);} @PostMapping("/{id}/info-responses") public Claim provideInfo(@PathVariable UUID id,@RequestParam String answer,@RequestHeader("X-User-Id") UUID user){return commands.provideInfo(id,user,answer);} }
